$target = Join-Path $PSScriptRoot '..\admin-panel\app\quran\page.tsx'
$source = Get-Content -LiteralPath $target -Raw -Encoding utf8
$source = [regex]::Replace($source, '<Link href="/">[^<]*Back to Dashboard</Link>', '<Link href="/">{"\u2039"} Back to Dashboard</Link>')
$source = [regex]::Replace($source, '<p>Add reviewed meanings once[^<]*</p>', '<p>Add reviewed meanings once and serve them from your own database - without repeated translation cost.</p>')
$source = [regex]::Replace($source, '<section className="steps">.*?</section>', '<section className="steps"><b>1<span>Choose language</span></b><i>-</i><b>2<span>Choose Surah</span></b><i>-</i><b>3<span>Add meanings</span></b><i>-</i><b>4<span>Review &amp; save</span></b></section>')
$source = [regex]::Replace($source, 'Step 1 [^<]* Content language<button', 'Step 1 - Content language<button')
$source = [regex]::Replace($source, '<em>[^<]* SAVED</em>', '<em>{"\u2713"} SAVED</em>')
$source = [regex]::Replace($source, '<strong>[^<]*</strong></button></label><label>Step 2 [^<]* Select Surah', '<strong>v</strong></button></label><label>Step 2 - Select Surah')
$source = [regex]::Replace($source, '\{x\.number\}\. \{x\.englishName\} [^<{]* \{x\.numberOfAyahs\} Ayahs', '{x.number}. {x.englishName} - {x.numberOfAyahs} Ayahs')
$source = [regex]::Replace($source, '<div className=\{completed===\(surah\?\.ayahs\?\.length\|\|0\)\?"savedLanguageBanner complete":"savedLanguageBanner"\}><i>[^<]*</i>', '<div className={completed===(surah?.ayahs?.length||0)?"savedLanguageBanner complete":"savedLanguageBanner"}><i>{"\u2713"}</i>')
$source = [regex]::Replace($source, '` [^$`]* \$\{\(surah\?\.ayahs', '` - ${(surah?.ayahs')
$source = [regex]::Replace($source, 'placeholder="Example: [^"]*"', 'placeholder="Enter localized name"', 1)
$source = [regex]::Replace($source, 'placeholder="Example: [^"]*"', 'placeholder="Enter Surah name meaning"', 1)
$source = [regex]::Replace($source, '<summary>Quick bulk paste [^<]* one Ayah meaning per line</summary>', '<summary>Quick bulk paste - one Ayah meaning per line</summary>')
$source = [regex]::Replace($source, 'placeholder="Find Ayah number or text[^"]*"', 'placeholder="Find Ayah number or text..."')
$source = [regex]::Replace($source, 'ORIGINAL [^<]* LOCKED', 'ORIGINAL - LOCKED')
$source = [regex]::Replace($source, 'meaning here[^`]*`', 'meaning here...`')
$source = [regex]::Replace($source, '\{values\[ayah\.numberInSurah\]\?\.trim\(\)\?"[^"]* Translation ready":"Not added yet"\}', '{values[ayah.numberInSurah]?.trim()?"\u2713 Translation ready":"Not added yet"}')
$source = [regex]::Replace($source, 'Step 4 [^<]* Review carefully', 'Step 4 - Review carefully')
$source = [regex]::Replace($source, '\{saving\?"Saving[^"]*":', '{saving?"Saving...":')
$source = [regex]::Replace($source, '<button type="button" onClick=\{\(\)=>\{setLanguageOpen\(false\);setLanguageSearch\(""\)\}\}>[^<]*</button>', '<button type="button" onClick={()=>{setLanguageOpen(false);setLanguageSearch("")}}>x</button>')
$source = [regex]::Replace($source, '<label className="languageSearch"><span>[^<]*</span>', '<label className="languageSearch"><span>?</span>')
$source = [regex]::Replace($source, '\$\{count\}/\$\{total\} Ayahs [^`]* Complete', '${count}/${total} Ayahs - Complete')
$source = [regex]::Replace($source, '\$\{count\}/\$\{total\} Ayahs [^`]* In progress', '${count}/${total} Ayahs - In progress')
$source = [regex]::Replace($source, '\{count>0\?<em>[^<]*</em>', '{count>0?<em>{"\u2713"}</em>')
$source = [regex]::Replace($source, '<strong>[^<]*</strong></button>\}\)</div>', '<strong>&gt;</strong></button>})</div>')
Set-Content -LiteralPath $target -Value $source -NoNewline -Encoding utf8
